INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, birth_day, birth_confidence, death_year, death_month, death_day, death_confidence, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('guo-east-zhong', '仲', ARRAY[]::text[], '姬', '虢', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '王季之子、周文王之弟，曾与虢叔同任文王卿士。周武王克商后分封二虢，通行说以虢仲封于制邑，为东虢始封君；东、西虢始封君的归属另有异说。生卒及具体在位起讫不详。', '[{"label":"虢仲（始封君归属异说及东虢世系待考区段）","url":"https://zh.wikipedia.org/wiki/虢仲"},{"label":"东虢国（始封与可考君主）","url":"https://zh.wikipedia.org/wiki/東虢國"}]'::jsonb, NULL, NULL, '虢仲')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, ancestral_xing = EXCLUDED.ancestral_xing, clan_shi = EXCLUDED.clan_shi, birth_year = EXCLUDED.birth_year, birth_month = EXCLUDED.birth_month, birth_day = EXCLUDED.birth_day, birth_confidence = EXCLUDED.birth_confidence, death_year = EXCLUDED.death_year, death_month = EXCLUDED.death_month, death_day = EXCLUDED.death_day, death_confidence = EXCLUDED.death_confidence, roles = EXCLUDED.roles, bio = EXCLUDED.bio, links = EXCLUDED.links, posthumous_name = EXCLUDED.posthumous_name, temple_name = EXCLUDED.temple_name, title = EXCLUDED.title;
INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, birth_day, birth_confidence, death_year, death_month, death_day, death_confidence, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('guo-east-dalin', '大林', ARRAY['虢惠叔大林','惠叔大林'], '姬', '虢', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '东虢君主，谥惠叔，虢叔旅之父。《虢叔旅钟》称“皇考惠叔大林”，记其侍奉周天子，旅作钟追念父亲。其与始封君虢仲之间的具体世系、生卒及在位起讫不详。', '[{"label":"东虢国（始封与可考君主）","url":"https://zh.wikipedia.org/wiki/東虢國"},{"label":"何志華《西周金文韻讀研究淺議》（虢叔旅钟、惠叔大林父子）","url":"https://jas.hkbu.edu.hk/content/dam/jas-assets/publications/bulletin-of-the-jao-tsung-i-academy-of-sinology/issue-6-august-2019/12.pdf"},{"label":"虢仲（始封君归属异说及东虢世系待考区段）","url":"https://zh.wikipedia.org/wiki/虢仲"}]'::jsonb, '惠叔', NULL, '虢惠叔')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, ancestral_xing = EXCLUDED.ancestral_xing, clan_shi = EXCLUDED.clan_shi, birth_year = EXCLUDED.birth_year, birth_month = EXCLUDED.birth_month, birth_day = EXCLUDED.birth_day, birth_confidence = EXCLUDED.birth_confidence, death_year = EXCLUDED.death_year, death_month = EXCLUDED.death_month, death_day = EXCLUDED.death_day, death_confidence = EXCLUDED.death_confidence, roles = EXCLUDED.roles, bio = EXCLUDED.bio, links = EXCLUDED.links, posthumous_name = EXCLUDED.posthumous_name, temple_name = EXCLUDED.temple_name, title = EXCLUDED.title;
INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, birth_day, birth_confidence, death_year, death_month, death_day, death_confidence, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('guo-east-lv', '旅', ARRAY['虢旅'], '姬', '虢', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '虢惠叔大林之子，西周虢国君主，东虢君主名录所载。曾作虢叔旅钟追念亡父，铭文记其承继父德、侍奉天子；《秦志》将其审理鬲从与攸卫牧田邑争讼系于前847年。生卒与完整在位起讫不详。', '[{"label":"东虢国（始封与可考君主）","url":"https://zh.wikipedia.org/wiki/東虢國"},{"label":"何志華《西周金文韻讀研究淺議》（虢叔旅钟、惠叔大林父子）","url":"https://jas.hkbu.edu.hk/content/dam/jas-assets/publications/bulletin-of-the-jao-tsung-i-academy-of-sinology/issue-6-august-2019/12.pdf"},{"label":"《陕西省志·秦志》大事年表（虢叔旅活动于前847年之说）","url":"https://dfz.shaanxi.gov.cn/zslm/fzzlk/xbsxsz/szdylpdf/201404/P020240923616206405975.pdf"},{"label":"虢仲（始封君归属异说及东虢世系待考区段）","url":"https://zh.wikipedia.org/wiki/虢仲"}]'::jsonb, NULL, NULL, '虢叔旅')
