INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, birth_day, birth_confidence, death_year, death_month, death_day, death_confidence, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('guo-east-last-shu', '？', ARRAY['东虢末君','东虢虢叔'], '姬', '虢', NULL, NULL, NULL, NULL, -767, 12, NULL, 'approximate_year', ARRAY['君主'], '东虢末代君主，史称虢叔，私名及父祖世系不详。《国语·郑语》记其与郑桓公同时；《左传·隐公元年》借郑庄公之言记“制，岩邑也，虢叔死焉”。东虢为郑所灭，通行系年为前767年；死亡方式未详。此人并非周文王之弟、西虢始封君虢叔。', '[{"label":"《左传·隐公元年》（制邑、虢叔死焉）","url":"https://zh.wikisource.org/wiki/春秋左氏傳/隱公"},{"label":"《国语·郑语》（虢叔与郑桓公共时）","url":"https://ctext.org/guo-yu/zheng-yu/ens"},{"label":"孙尚勇《〈春秋〉历史叙事与孔子的文化关怀》（平王四年郑灭虢与杜预注）","url":"https://www.ica.org.cn/att/site17/20240529/1716968303123.pdf"},{"label":"东虢国（始封与可考君主）","url":"https://zh.wikipedia.org/wiki/東虢國"},{"label":"虢仲（始封君归属异说及东虢世系待考区段）","url":"https://zh.wikipedia.org/wiki/虢仲"}]'::jsonb, NULL, NULL, '虢叔')
